insert into weeks (week_start, era, theme, content) values ('2026-10-19', '先秦', '诗经 · 风雅之始', $json${"intro":"**欢迎来到一日一诗。**接下来十二周，我们会从三千年前的河边一路读到明清。每个月一个时代，每周一个主题，每天一首诗、一个你可能还不认识的成语。\n\n第一站是《诗经》。它是中国最早的诗歌总集，收了西周初年到春秋中期大约五百年间的三百零五篇诗，分成「风」「雅」「颂」三类。「风」是各地的民歌，「雅」是朝廷宴会的乐歌，「颂」是祭祀用的颂歌。这一周我们读的大多是「风」：普通人的恋爱、婚嫁、劳作、抱怨和思乡。\n\n读的时候留意两件事。一是**兴**：先写眼前的鸟、草、树，再引出心里的话。二是**重章叠句**：同一段话换几个字反复唱。它们原本都是配乐唱的歌，所以读出声来最有味道。\n\n本周的七个成语，全都出自《诗经》，有几个就藏在当天的诗里。","preview":["周一　关雎 · 寤寐思服","周二　蒹葭 · 秋水伊人","周三　子衿 · 风雨如晦","周四　桃夭 · 宜室宜家","周五　氓 · 二三其德","周六　硕鼠 · 爰得我所","周日　采薇 · 雨雪霏霏"]}$json$::jsonb)
on conflict (week_start) do update set era = excluded.era, theme = excluded.theme, content = excluded.content, updated_at = now();

insert into issues (date, week_start, theme, content, approved) values ('2026-10-19', '2026-10-19', '诗经 · 风雅之始', $json${"greeting":"**早安。**关关{雎鸠|jū jiū}，在河之洲。三千年前的鸟已经叫了，你也该起床了。","chengyu":{"word":"寤寐思服","pinyin":"wù mèi sī fú","meaning":"醒着想，睡着也想，形容日日夜夜都在思念。{寤|wù}是醒，{寐|mèi}是睡，「思」和「服」都是想念。","examples":["出国交换半年，我最寤寐思服的不是家，是我妈煮的那锅汤。","那双限量球鞋我寤寐思服了一整年，今天终于抢到了！"],"note":"语气偏书面，正经地用很典雅，用来调侃日常小事也很有趣。它思念的是人或物，不能用来说「反复思考一个问题」。","origin":"出自今天的诗《关雎》。紧接着的下一句，就是你早就熟悉的「辗转反侧」。原来这两个成语是一对，前一句说想念，后一句说想得睡不着。"},"poem":{"title":"关雎","source":"《诗经 · 周南》","image":"/poems/guanju.png","lines":["关关雎鸠，在河之洲。窈窕淑女，君子好逑。","参差荇菜，左右流之。窈窕淑女，寤寐求之。","求之不得，寤寐思服。悠哉悠哉，辗转反侧。","参差荇菜，左右采之。窈窕淑女，琴瑟友之。","参差荇菜，左右{芼|mào}之。窈窕淑女，钟鼓{乐|lè}之。"],"summary":"河边的水鸟一声声和鸣，引出一个青年对姑娘的思慕。他想她想得睡不着，又幻想着弹琴鼓瑟去亲近她，最后敲钟打鼓迎娶她。全诗从相思写到成婚，感情热烈，却始终有分寸。","notes":[{"term":"关关","gloss":"雎鸠的叫声，是拟声词。"},{"term":"{窈窕|yǎo tiǎo}","gloss":"幽静美好的样子。"},{"term":"{好逑|hǎo qiú}","gloss":"好的配偶。「逑」就是配偶。"},{"term":"{参差|cēn cī}{荇菜|xìng cài}","gloss":"长短不齐的荇菜，一种可以吃的水草。"},{"term":"流之","gloss":"顺着水流去捞取。后面的「采之」「芼之」也都是采摘的意思。"},{"term":"琴瑟友之、钟鼓乐之","gloss":"用琴瑟去亲近她，用钟鼓让她快乐。诗到这里，已经从追求写到了迎娶。"}],"technique":"诗以水鸟和鸣开篇，借眼前的景物引出要说的情感，这叫「**兴**」，是《诗经》最典型的手法。三次写采荇菜，每次只换一个动词（流、采、芼），这种「**重章叠句**」让感情一层层推进。这两个术语写华文赏析题时都用得上。","history":{"title":"一首情歌，怎么成了道德课本？","body":"《诗经》是中国最早的诗歌总集，收录了西周初年到春秋中期的三百零五篇诗，《关雎》排在第一篇。孔子评价它「乐而不{淫|yín}，哀而不伤」：快乐却不放纵，忧伤却不过度。\n\n到了汉代，汉武帝独尊儒术，《诗经》被列为五经之一，成了官方经典。当时解诗的《毛诗序》说《关雎》歌颂的是「后妃之德」，把一首民间情歌读成了宫廷道德教材。直到宋代以后，才陆续有学者主张回到诗句本身，把它当作爱情诗来读。\n\n所以《关雎》能排在三百篇之首，不只是因为写得好，也因为两千年来每个时代都在借它说自己想说的话。"}},"appreciation":{"type":"字词流变","title":"「窈窕」的变身","body":"今天的减肥广告爱说「窈窕身材」，意思是苗条。可在《关雎》里，「窈窕」原本形容的是幽静美好的样子。古人注释还有「善心为窈，善容为窕」的说法，一半说内在，一半说仪态，跟腰围没什么关系。\n\n三千年下来，一个词从「心灵美」变成了「瘦」。下次看到这类广告，你可以默默纠正一下。"},"signoff":"**明天见。**今晚，希望你不必寤寐思服，一觉睡到天亮。"}$json$::jsonb, true)
on conflict (date) do update set week_start = excluded.week_start, theme = excluded.theme, content = excluded.content, approved = excluded.approved, updated_at = now();

